import json,pathlib,sys
homes=json.loads(sys.argv[1])
matches=[]
for item in pathlib.Path('/proc').glob('[0-9]*/cmdline'):
    try:
        args=item.read_bytes().split(bytes([0]))
    except (FileNotFoundError,PermissionError):
        continue
    for home in homes:
        if str(pathlib.Path(home)/'desktop/postgres').encode() in args and b'postgres' in args[0]:
            matches.append({'pid':item.parent.name,'home':home})
result={'homes':[{ 'home':home,'exists':pathlib.Path(home).exists()} for home in homes],'matchingPostgres':matches}
assert not matches and all(not item['exists'] for item in result['homes']),result
print(json.dumps(result))
